p=argparse.ArgumentParser();p.add_argument('--file-read-delay-ms',type=int,default=250);p.add_argument('--entry',default='Ranger-Kompakt.html');p.add_argument('--site',default='outputs');p.add_argument('--output',default='work/qa-correction/import-browser');a=p.parse_args()
if not 0<=a.file_read_delay_ms<=5000:p.error('file read delay must be 0–5000 ms')
root=Path(__file__).resolve().parents[1];out=root/a.output;out.mkdir(parents=True,exist_ok=True);key='ranger-compact-fieldbook-v2';valid=json.loads((root/'verification/kompakt-v2/learning/earned-all-families.json').read_text());r={'entry':a.entry,'scope':'Rendered DOM plus actual WebGL boot of standalone HTML; imports/storage corruption are explicitly labelled fixtures, not newly earned mission evidence','baselineFixtureProvenance':'Two preserved historical own reconstructions, not claimed byte-identical to the unavailable independent archive originals','fileReadLatencyFixtureMs':a.file_read_delay_ms,'responseWait':'Fresh preview DOM mutation, not stale text or an arbitrary sleep','checks':[],'errors':[],'passed':False,'htmlSHA256':hashlib.sha256((root/a.site/a.entry).read_bytes()).hexdigest()}
class Handler(SimpleHTTPRequestHandler):
 def log_message(self,*args):pass
server=ThreadingHTTPServer(('127.0.0.1',0),partial(Handler,directory=str(root/a.site)));Thread(target=server.serve_forever,daemon=True).start();url=f'http://127.0.0.1:{server.server_port}/{a.entry}'
def save():(out/'result.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
def boot(page):
 page.set_default_timeout(45000);page.on('pageerror',lambda e:r['errors'].append(str(e)))
 # Explicit file-I/O latency fixture only. Original file bytes/native read remain
 # unchanged; this is neither a world-time nor an observation-evidence injection.
 if a.file_read_delay_ms:page.add_init_script('const originalFileText=File.prototype.text;File.prototype.text=async function(){await new Promise(resolve=>setTimeout(resolve,'+str(a.file_read_delay_ms)+'));return originalFileText.call(this);};')
 page.goto(url);page.wait_for_function('document.querySelector("#world").dataset.ready==="true"',timeout=120000);page.locator('#start').click()
def storage(page):return page.evaluate('(key)=>localStorage.getItem(key)',key)

def context_fixture(before):
 # Explicit synthetic import fixture built from a valid old fixed-individual
 # record; it is never counted as newly acquired observation evidence.
 old=json.loads(before)['records'][0];old['simulationTime']=240;old['events']=[]
 old['note']='QA import fixture: old context; not a newly earned observation.'
 new=json.loads(json.dumps(old));new.update(id='qa-new-context-record',runId='qa-local-import-run',simulationTime=6,note='QA import fixture: explicit local context; not a newly earned observation. <em data-qa-html-note="literal">Nur Text</em>')
 new['sceneOrigin']={'kind':'local-observation-window','previousRunId':old['runId'],'previousSimulationTime':240,'siteId':'coast','x':63,'z':-12,'startSimulationTime':0}
 return {'schemaVersion':2,'worldVersion':old['worldVersion'],'records':[old,new],'archives':[],'previousEditions':[],'learning':{'activeMission':None,'level':'gA','answers':{},'drafts':{},'protocols':[],'measurements':[],'samples':[],'experiments':[]}}

def event_reference_fixtures():
 # Model events are generated by the current Node model, but observation rows
 # and their three-second durations are explicit import fixtures, not live QA
 # evidence. Keeping the source local avoids a stale embedded event snapshot.
 script=r"""
import { createReferenceState,stepReference } from './dist/compact/world-state.js';
import { createEcology,stepEcology } from './dist/compact/ecology.js';
import { localObservationContext } from './dist/compact/observation-context.js';
import { observationSite } from './dist/compact/observation-schema.js';
import { WORLD_VERSION } from './dist/compact/manifest.js';
import { emptyLearning } from './dist/compact/missions.js';
const observer={x:63,z:-12},advance=s=>{for(let i=0;i<100;i++){stepReference(s,.1,observer);stepEcology(s,.1,observer);}};
const old=createReferenceState();createEcology(old);advance(old);
const next=localObservationContext(old,observer,{runId:'qa-event-prior',newRunId:'qa-event-local',siteId:'coast'});advance(next.state);
const row=(s,id,runId,sceneOrigin)=>{const event=s.ecology.events.find(e=>e.interaction==='bee-clover'),actor=s.ecology.actors.find(a=>a.id===event.actors[0]);return {id,taxon:actor.taxon,individualId:actor.id,worldVersion:WORLD_VERSION,initialSeed:s.initialSeed,modelRevision:s.modelRevision,window:s.ecology.window,runId,...(sceneOrigin?{sceneOrigin}:{}),source:'own-observation',observationSeconds:3,simulationTime:s.time,x:actor.x,z:actor.z,siteId:observationSite(actor.x),method:'magnified-active-model',note:'QA import fixture only: generated model event, synthetic observation duration; not newly earned evidence.',events:[structuredClone(event)]};};
const first=row(old,'qa-old-event-note','qa-event-prior'),second=row(next.state,'qa-new-event-note',next.runId,next.sceneOrigin);
if(first.events[0].id!==second.events[0].id)throw Error('Expected real local event-ID collision');
const answer={caseId:'bee-clover',eventIds:[first.events[0].id],claim:'event-with-resource',alternative:'no-seed-guarantee',reasoning:'Labelled import fixture: the event documents pollen transfer without proving seed set.'};
const book=records=>({schemaVersion:2,worldVersion:WORLD_VERSION,records,archives:[],previousEditions:[],learning:{...emptyLearning(),activeMission:'K2',answers:{K2:structuredClone(answer)},drafts:{K2:structuredClone(answer)}}});
console.log(JSON.stringify({single:book([first]),repeated:book([first,{...structuredClone(first),id:'qa-repeat-note-same-event'}]),ambiguous:book([first,second])}));
"""
 return json.loads(subprocess.run(['node','--input-type=module','-e',script],cwd=root,capture_output=True,text=True,check=True).stdout)

def event_reference_checks(page):
 for name,fixture in event_reference_fixtures().items():
  filename='labelled-legacy-event-'+name+'.json';fixture_path=out/filename;fixture_path.write_text(json.dumps(fixture,ensure_ascii=False,indent=2)+'\n')
  choose_import_file(page,str(fixture_path));page.locator('#apply-import').click();original=storage(page)
  assert json.loads(original)==fixture
  page.locator('#close').click();page.wait_for_function('(complete)=>JSON.parse(document.querySelector("#world").dataset.missions).find(m=>m.id==="K2").complete===complete',arg=name!='ambiguous')
  page.locator('#objective').click();page.locator('#panel [data-mission="K2"]').click()
  assert storage(page)==original
  assert page.locator('input[name="event-ids"]').count()==len(fixture['records'])
  assert page.locator('input[name="event-ids"]:checked').count()==(0 if name=='ambiguous' else len(fixture['records']))
  assert page.locator('#event-reference-warning').count()==int(name=='ambiguous')
  check={'name':'legacy event reference '+name+' imports and renders without silent reassignment','passed':True,'fixtureNotEarnedEvidence':True,'fixture':filename,'fixtureSHA256':hashlib.sha256(fixture_path.read_bytes()).hexdigest(),'oldStorageByteIdenticalOnOpen':True,'automaticK2Complete':name!='ambiguous'}
  if name=='ambiguous':
   assert 'mehrdeutig' in page.locator('#event-reference-warning').inner_text();page.screenshot(path=str(out/'legacy-ambiguous-selection.png'))
   page.locator('input[name="event-ids"]').nth(1).check();page.locator('#save-task').click()
   assert page.locator('#task-feedback').inner_text().startswith('Strukturierte Belegprüfung erfüllt.')
   assert page.locator('#event-reference-warning').count()==0
   expected=json.dumps(['record-event-v1',fixture['records'][1]['id'],fixture['records'][1]['events'][0]['id']],separators=(',',':'))
   selected=json.loads(storage(page));assert selected['records']==fixture['records'];assert selected['learning']['answers']['K2']['eventIds']==[expected]
   page.wait_for_function('JSON.parse(document.querySelector("#world").dataset.missions).find(m=>m.id==="K2").complete===true');page.screenshot(path=str(out/'legacy-explicit-qualified-selection.png'))
   check.update(explicitReselectionCompleted=True,qualifiedReference=expected,screenshots=['legacy-ambiguous-selection.png','legacy-explicit-qualified-selection.png'])
  page.locator('#close').click();page.locator('#journal-button').click()
  with page.expect_download()as dl:page.locator('#export').click()
  exported=out/('legacy-event-'+name+'-export.json');dl.value.save_as(str(exported));export_data=json.loads(exported.read_text());assert export_data['records']==fixture['records']
  expected_answer=selected['learning']['answers']['K2'] if name=='ambiguous' else fixture['learning']['answers']['K2'];assert export_data['learning']['answers']['K2']==expected_answer
  choose_import_file(page,str(exported));page.locator('#apply-import').click();assert json.loads(storage(page))['learning']['answers']['K2']==expected_answer
  check.update(export=exported.name,exportSHA256=hashlib.sha256(exported.read_bytes()).hexdigest());r['checks'].append(check);save()

def import_cases(before):
 cases=[]
 def add(name,data):cases.append((name,json.dumps(data,ensure_ascii=False)))
 for name in ['repro-invalid-top-level-features.json','repro-impossible-coordinates.json']:
  # Preserve these historical OWN-reconstruction fixture bytes. The two
  # original independent archive files were not available for byte comparison.
  cases.append((name,(root/'verification/kompakt-korrektur/baseline'/name).read_text()))
 for field,value in [('features',{}),('recordId',3),('choice',[]),('limit',False)]:
  d=json.loads(before);d['learning']['drafts']['K1']={field:value};add('K1-'+field,d)
 for name,value in [('not-array',1),('null-item',[None]),('nested-features',[{'recordId':json.loads(before)['records'][0]['id'],'features':{}}])]:
  d=json.loads(before);d['learning']['drafts']['K1']={'determinations':value};add('K1-determinations-'+name,d)
 d=json.loads(before);d['learning']['drafts']['K2']={'experimentTide':{}};add('K2-experimentTide',d)
 # Isolate records so unrelated strict K3 data cannot mask observation errors.
 def isolated():
  d=json.loads(before);d['records']=[d['records'][0]];d['learning']=context_fixture(before)['learning'];return d
 for value in [0,False,'',None,'toString','constructor']:
  d=isolated();d['records'][0]['window']=value;add('isolated-window-'+json.dumps(value),d)
 for name,field,value in [('outside-world','x',999999),('unknown-method','method','invented-observation'),('unknown-individual','individualId','not-a-real-individual'),('wrong-site','siteId','compact-wadden'),('empty-run','runId',''),('negative-model-time','simulationTime',-1)]:
  d=isolated();d['records'][0][field]=value;add(name,d)
 d=isolated();d['records'][0]['x']+=1;add('fixed-plant-shifted-one-metre',d)
 cases.extend([('invalid-json','{broken'),('null-top-level','null'),('array-top-level','[]')])
 d=json.loads(before);overlap=json.loads(json.dumps(d['learning']['protocols'][0]));overlap['id']='qa-overlapping-protocol';d['learning']['protocols'].append(overlap);add('overlapping-protocol',d)
 d=json.loads(before);d['learning']['samples'][0]['areaM2']+=.1;add('wrong-sample-area',d)
 d=json.loads(before);d['learning']['experiments'][0]['result']['yield']+=1;add('invented-experiment-yield',d)
 for name in ['own-run','wrong-location','unknown-site','backward-parent-time','missing-origin-in-run','changed-origin-in-run','cyclic-origin','nonzero-start','reused-run-id','null-origin','extra-origin-field']:
  d=context_fixture(before);old,new=d['records'];origin=new['sceneOrigin']
  if name=='own-run':origin['previousRunId']=new['runId']
  elif name=='wrong-location':origin['x']=-60
  elif name=='unknown-site':origin['siteId']='invented-coastal-site'
  elif name=='backward-parent-time':origin['previousSimulationTime']=239
  elif name in ['missing-origin-in-run','changed-origin-in-run']:
   another=json.loads(json.dumps(new));another['id']='qa-context-copy';d['records'].append(another)
   if name=='missing-origin-in-run':del new['sceneOrigin']
   else:origin['previousSimulationTime']=241
  elif name=='cyclic-origin':old['sceneOrigin']={**origin,'previousRunId':new['runId'],'previousSimulationTime':1200}
  elif name=='nonzero-start':origin['startSimulationTime']=1
  elif name=='reused-run-id':new['runId']=old['runId']
  elif name=='null-origin':new['sceneOrigin']=None
  elif name=='extra-origin-field':origin['unverifiedFlag']=True
  add('sceneOrigin-'+name,d)
 return cases
